#!/usr/bin/env node  import { spawn } from 'node:child_process'; import { createWriteStream } from 'node:fs'; import { appendFile, cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises'; import path from 'node:path'; import process from 'node:process';  const FRONTEND_ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..'); const REPO_ROOT = path.resolve(FRONTEND_ROOT, '..'); const DELIVERABLE_ROOT = path.resolve(   REPO_ROOT,   'execution/PKG-03_Harness_Runtime_Core/1_Working/DEL-03-06_Outbound_Network_Guardrails' );  const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '::1', '[::1]']); const ALLOWLIST_HOSTS = new Set(['api.anthropic.com']);  const DEFAULT_RUN_COUNT = 3; const DEFAULT_IDLE_SECONDS = 600; const DEFAULT_IDLE_SAMPLE_SECONDS = 60; const DEFAULT_HTTP_TIMEOUT_MS = 120_000; const DEFAULT_STARTUP_WAIT_MS = 4000;  function timestampForPath(date = new Date()) {   return date.toISOString().replace(/[:]/g, '').replace(/\..+$/, '').replace('T', '_'); }  function parseIntegerArg(value, fallback) {   if (value === undefined) {     return fallback;   }    const parsed = Number.parseInt(value, 10);   if (!Number.isSafeInteger(parsed) || parsed <= 0) {     return fallback;   }    return parsed; }  function parseArgs(argv) {   const args = {     runs: DEFAULT_RUN_COUNT,     idleSeconds: DEFAULT_IDLE_SECONDS,     idleSampleSeconds: DEFAULT_IDLE_SAMPLE_SECONDS,     outputDir: path.resolve(       DELIVERABLE_ROOT,       'Evidence',       `OI-002_PROOF_${timestampForPath()}`     )   };    for (let index = 0; index < argv.length; index += 1) {     const token = argv[index];      if (token === '--runs' && argv[index + 1]) {       args.runs = parseIntegerArg(argv[index + 1], args.runs);       index += 1;       continue;     }      if (token === '--idle-seconds' && argv[index + 1]) {       args.idleSeconds = parseIntegerArg(argv[index + 1], args.idleSeconds);       index += 1;       continue;     }      if (token === '--idle-sample-seconds' && argv[index + 1]) {       args.idleSampleSeconds = parseIntegerArg(argv[index + 1], args.idleSampleSeconds);       index += 1;       continue;     }      if (token === '--output-dir' && argv[index + 1]) {       args.outputDir = path.resolve(argv[index + 1]);       index += 1;     }   }    return args; }  function sleep(ms) {   return new Promise((resolve) => {     setTimeout(resolve, ms);   }); }  function toIsoNow() {   return new Date().toISOString(); }  function parseRemoteHost(remote) {   if (!remote) {     return '';   }    if (remote.startsWith('[')) {     const close = remote.indexOf(']');     if (close > 1) {       return remote.slice(1, close);     }   }    const lastColon = remote.lastIndexOf(':');   if (lastColon > 0) {     return remote.slice(0, lastColon);   }    return remote; }  function classifyRemoteHost(host) {   const normalized = host.trim().toLowerCase();   if (!normalized) {     return 'unknown';   }    if (LOOPBACK_HOSTS.has(normalized)) {     return 'loopback';   }    if (ALLOWLIST_HOSTS.has(normalized)) {     return 'allowlisted';   }    if (normalized.endsWith('.anthropic.com')) {     return 'anthropic_non_allowlisted';   }    return 'external_non_allowlisted'; }  function parseLsofTcp(output) {   const lines = output.split(/?
/).map((line) => line.trim()).filter(Boolean);   const remoteEndpoints = [];   for (const line of lines) {     if (!line.includes('->')) {       continue;     }      const arrowIndex = line.indexOf('->');     const remoteField = line.slice(arrowIndex + 2).split(' ')[0];     const remoteHost = parseRemoteHost(remoteField);     remoteEndpoints.push({       endpoint: remoteField,       host: remoteHost,       class: classifyRemoteHost(remoteHost)     });   }    return {     rawLineCount: lines.length,     remoteEndpoints   }; }  async function runCommand(command, args, options = {}) {   return new Promise((resolve) => {     const child = spawn(command, args, {       cwd: options.cwd,       env: options.env,       stdio: ['ignore', 'pipe', 'pipe']     });      let stdout = '';     let stderr = '';      child.stdout.on('data', (chunk) => {       stdout += chunk.toString();     });      child.stderr.on('data', (chunk) => {       stderr += chunk.toString();     });      child.on('close', (code) => {       resolve({ code: code ?? 1, stdout, stderr });     });   }); }  function startLoggedProcess({ label, command, args, cwd, env, logPath }) {   const child = spawn(command, args, {     cwd,     env,     stdio: ['ignore', 'pipe', 'pipe']   });    const stream = createWriteStream(logPath, { flags: 'a' });   stream.write(`[${toIsoNow()}] START ${label}: ${command} ${args.join(' ')}
`);    child.stdout.on('data', (chunk) => {     stream.write(chunk);   });    child.stderr.on('data', (chunk) => {     stream.write(chunk);   });    child.on('close', (code, signal) => {     stream.write(`[${toIsoNow()}] EXIT ${label}: code=${code ?? 'null'} signal=${signal ?? 'null'}
`);   });    return { child, stream }; }  async function stopProcess(child, label, timeoutMs = 10_000) {   if (!child || child.exitCode !== null) {     return;   }    child.kill('SIGTERM');   const start = Date.now();    while (child.exitCode === null && Date.now() - start < timeoutMs) {     await sleep(100);   }    if (child.exitCode === null) {     child.kill('SIGKILL');     const hardStart = Date.now();     while (child.exitCode === null && Date.now() - hardStart < 2000) {       await sleep(50);     }   }    if (child.exitCode === null) {     throw new Error(`Failed to stop ${label} process`);   } }  async function waitForHttpReady(url, timeoutMs, processToWatch) {   const started = Date.now();    while (Date.now() - started < timeoutMs) {     if (processToWatch && processToWatch.exitCode !== null) {       throw new Error(`Observed process exit before HTTP readiness at ${url}`);     }      try {       const response = await fetch(url, { method: 'GET' });       if (response.ok || response.status === 404) {         return;       }     } catch {       // keep waiting until timeout     }      await sleep(500);   }    throw new Error(`Timed out waiting for HTTP readiness at ${url}`); }  async function postJson(url, payload) {   const response = await fetch(url, {     method: 'POST',     headers: {       'Content-Type': 'application/json'     },     body: JSON.stringify(payload)   });    const text = await response.text();   let parsed = null;   try {     parsed = JSON.parse(text);   } catch {     // no-op: preserve raw text   }    return {     status: response.status,     ok: response.ok,     raw: text,     parsed   }; }  async function postTurnSse(url, payload) {   const response = await fetch(url, {     method: 'POST',     headers: {       'Content-Type': 'application/json'     },     body: JSON.stringify(payload)   });    const text = await response.text();   const events = [];    let currentEvent = null;   let currentData = [];    for (const line of text.split(/?
/)) {     if (line.startsWith('event:')) {       currentEvent = line.slice('event:'.length).trim();       continue;     }      if (line.startsWith('data:')) {       currentData.push(line.slice('data:'.length).trim());       continue;     }      if (line.trim().length === 0 && currentEvent) {       const dataString = currentData.join('
');       let parsed = null;       try {         parsed = JSON.parse(dataString);       } catch {         parsed = null;       }        events.push({         event: currentEvent,         rawData: dataString,         data: parsed       });        currentEvent = null;       currentData = [];     }   }    return {     status: response.status,     ok: response.ok,     raw: text,     events   }; }  async function captureTcpSnapshot({ runDir, label, processLabel, pid }) {   const capture = {     timestamp: toIsoNow(),     label,     processLabel,     pid,     lsofExitCode: 0,     raw: '',     parsed: {       rawLineCount: 0,       remoteEndpoints: []     }   };    if (!Number.isSafeInteger(pid) || pid

#!/usr/bin/env node  import { cp, mkdir, readFile, rm, stat, writeFile } from 'node:fs/promises'; import { existsSync } from 'node:fs'; import os from 'node:os'; import path from 'node:path';  const HARNESS_BASE_URL = process.env.HARNESS_BASE_URL ?? 'http://127.0.0.1:3000'; const TMP_ROOT = path.join(   process.env.TMPDIR ?? os.tmpdir(),   'chirality-harness-validation',   'latest' ); const OUTPUT_DIRS = {   api: path.join(TMP_ROOT, 'api'),   sse: path.join(TMP_ROOT, 'sse'),   logs: path.join(TMP_ROOT, 'logs'),   cleanup: path.join(TMP_ROOT, 'cleanup') };  const REQUIRED_CHECK_ORDER = [   'setup.server_reachable',   'regression.session_crud',   'section8.boot_error_taxonomy',   'section8.smoke_stream',   'section8.session_persistence_resume',   'section8.permissions_dontask',   'section8.interrupt_sigint',   'section8.sdk_native_stream' ];  const encoder = new TextEncoder(); const decoder = new TextDecoder();  function nowIso() {   return new Date().toISOString(); }  function sleep(ms) {   return new Promise((resolve) => {     setTimeout(resolve, ms);   }); }  function urlFor(pathname, params = {}) {   const url = new URL(pathname, HARNESS_BASE_URL);   for (const [key, value] of Object.entries(params)) {     url.searchParams.set(key, value);   }   return url.toString(); }  function resolveProjectRoot() {   if (process.env.HARNESS_PROJECT_ROOT) {     return path.resolve(process.env.HARNESS_PROJECT_ROOT);   }    const candidates = [     path.resolve(process.cwd(), '..', 'examples', 'example-project'),     path.resolve(process.cwd(), '..', '..', '..', 'examples', 'example-project')   ];    return (     candidates.find((candidate) => existsSync(candidate)) ??     path.join(TMP_ROOT, 'workroots', 'default-project-root')   ); }  function resolveInstructionRoot() {   const candidates = [     process.env.CHIRALITY_INSTRUCTION_ROOT       ? path.resolve(process.env.CHIRALITY_INSTRUCTION_ROOT)       : undefined,     path.resolve(process.cwd(), '..'),     path.resolve(process.cwd(), '..', '..', '..')   ].filter(Boolean);    return candidates.find((candidate) => existsSync(path.join(candidate, 'agents'))) ?? candidates[0]; }  function isPathWithin(basePath, targetPath) {   const relative = path.relative(basePath, targetPath);   return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative)); }  async function assertDirectoryExists(dirPath, label) {   let directoryStat;   try {     directoryStat = await stat(dirPath);   } catch {     throw new Error(`${label} must point to an existing directory: ${dirPath}`);   }    if (!directoryStat.isDirectory()) {     throw new Error(`${label} must point to an existing directory: ${dirPath}`);   } }  async function prepareProjectRoot(requestedProjectRoot) {   await assertDirectoryExists(requestedProjectRoot, 'HARNESS_PROJECT_ROOT');    const instructionRoot = resolveInstructionRoot();   if (!isPathWithin(instructionRoot, requestedProjectRoot)) {     return {       effectiveProjectRoot: requestedProjectRoot,       stagedFromInstructionRoot: false     };   }    const stagedProjectRoot = path.join(TMP_ROOT, 'workroots', 'staged-project-root');   await rm(stagedProjectRoot, { recursive: true, force: true });   await mkdir(path.dirname(stagedProjectRoot), { recursive: true });   await cp(requestedProjectRoot, stagedProjectRoot, { recursive: true });    return {     effectiveProjectRoot: stagedProjectRoot,     stagedFromInstructionRoot: true   }; }  function parseSse(raw) {   const events = [];   const segments = raw.split('

');    for (const segment of segments) {     const lines = segment.trim().split('
').filter(Boolean);     if (lines.length === 0) {       continue;     }      let eventType = null;     const dataLines = [];      for (const line of lines) {       if (line.startsWith('event:')) {         eventType = line.slice('event:'.length).trim();       } else if (line.startsWith('data:')) {         dataLines.push(line.slice('data:'.length).trim());       }     }      if (!eventType) {       continue;     }      let data = null;     if (dataLines.length) {       try {         data = JSON.parse(dataLines.join('
'));       } catch {         data = dataLines.join('
');       }     }      events.push({ type: eventType, data });   }    return events; }  function assert(condition, message) {   if (!condition) {     throw new Error(message);   } }  function assertOrderedEvents(events, expectedOrder) {   let previousIndex = -1;   for (const type of expectedOrder) {     const index = events.findIndex((event, idx) => idx > previousIndex && event.type === type);     if (index < 0) {       throw new Error(`Missing ordered SSE event '${type}'`);     }     previousIndex = index;   } }  function testResultToLog(result) {   const output = {     id: result.id,     status: result.status,     startedAt: result.startedAt,     endedAt: result.endedAt,     durationMs: result.durationMs   };   if (result.details !== undefined) {     output.details = result.details;   }   if (result.error !== undefined) {     output.error = result.error;   }   return output; }  async function ensureOutputLayout() {   await rm(TMP_ROOT, { recursive: true, force: true });   await mkdir(OUTPUT_DIRS.api, { recursive: true });   await mkdir(OUTPUT_DIRS.sse, { recursive: true });   await mkdir(OUTPUT_DIRS.logs, { recursive: true });   await mkdir(OUTPUT_DIRS.cleanup, { recursive: true }); }  async function writeJson(filePath, payload) {   await writeFile(filePath, `${JSON.stringify(payload, null, 2)}
`, 'utf8'); }  async function writeText(filePath, text) {   await writeFile(filePath, text, 'utf8'); }  async function requestJson(pathname, { method = 'GET', body, query } = {}) {   const response = await fetch(urlFor(pathname, query), {     method,     headers: {       'Content-Type': 'application/json'     },     body: body ? JSON.stringify(body) : undefined   });    let payload = null;   try {     payload = await response.json();   } catch {     payload = null;   }    return { response, payload }; }  async function requestSse(pathname, body) {   const response = await fetch(urlFor(pathname), {     method: 'POST',     headers: {       'Content-Type': 'application/json'     },     body: JSON.stringify(body)   });   const raw = await response.text();   const events = parseSse(raw);   return { response, raw, events }; }  async function requestSseWithInterrupt(pathname, body, sessionId) {   const response = await fetch(urlFor(pathname), {     method: 'POST',     headers: {       'Content-Type': 'application/json'     },     body: JSON.stringify(body)   });    assert(response.ok, `Turn request failed with HTTP ${response.status}`);   assert(response.body, 'Expected readable SSE body');    let raw = '';   let interruptPayload = null;   let interruptStatus = null;   let interruptSent = false;    const interruptPromise = (async () => {     await sleep(50);     interruptSent = true;     const startedAt = Date.now();     const retryWindowMs = 2000;     const retryDelayMs = 50;      while (Date.now() - startedAt <= retryWindowMs) {       const interrupt = await requestJson('/api/harness/interrupt', {         method: 'POST',         body: { sessionId }       });       interruptStatus = interrupt.response.status;       interruptPayload = interrupt.payload;        if (interruptStatus !== 404) {         return;       }        await sleep(retryDelayMs);     }   })();    const reader = response.body.getReader();    while (true) {     const chunk = await reader.read();     if (chunk.done) {       break;     }      raw += decoder.decode(chunk.value, { stream: true });   }    await interruptPromise;   raw += decoder.decode(encoder.encode(''), { stream: false });   const events = parseSse(raw);   return { response, raw, events, interruptStatus, interruptPayload, interruptSent }; }  async function main() {   await ensureOutputLayout();    const requestedProjectRoot = resolveProjectRoot();   if (!process.env.HARNESS_PROJECT_ROOT && requestedProjectRoot.startsWith(TMP

- 2026-02-24 - State set to ${state} (WORKING_ITEMS) `; }  async function createDeliverable(   pkgFolder: string,   deliverableFolder: string,   state: string,   files: string[] ): Promise<string> {   const deliverablePath = path.join(projectRoot, pkgFolder, '1_Working', deliverableFolder);   await mkdir(deliverablePath, { recursive: true });   await writeFile(path.join(deliverablePath, '_STATUS.md'), statusDocument(state), 'utf8');    for (const fileName of files) {     await writeFile(path.join(deliverablePath, fileName), `${fileName} content`, 'utf8');   }    return deliverablePath; }  async function importRouteModule(): Promise<RouteModule> {   vi.resetModules();   return import('../../../app/api/project/deliverables/route'); }  async function requestDeliverables(rootPath: string): Promise<{ status: number; body: RouteBody }> {   const route = await importRouteModule();   const response = await route.GET(     new Request(       `http://localhost/api/project/deliverables?projectRoot=${encodeURIComponent(rootPath)}`     )   );    return {     status: response.status,     body: (await response.json()) as RouteBody   }; }  beforeEach(async () => {   tmpRoot = await mkdtemp(path.join(os.tmpdir(), 'chirality-project-deliverables-route-'));   projectRoot = path.join(tmpRoot, 'project-root');   await mkdir(projectRoot, { recursive: true }); });  afterEach(async () => {   await rm(tmpRoot, { recursive: true, force: true });   tmpRoot = '';   projectRoot = ''; });  describe('GET /api/project/deliverables', () => {   it('returns deliverables, knowledge marker metadata, and knowledge type mappings', async () => {     const deliverablePath = await createDeliverable(       'PKG-02_Desktop_UI_Workflow',       'DEL-02-02_Portal_Pipeline_Navigation',       'IN_PROGRESS',       ['Datasheet.md', 'Specification.md', 'MEMORY.md']     );      const decompositionPath = path.join(projectRoot, '_Decomposition');     await mkdir(decompositionPath, { recursive: true });     await writeFile(       path.join(decompositionPath, 'Domain_Handbook.md'),       '# Knowledge Types

Knowledge Categories and Knowledge Types are defined here.',       'utf8'     );      const response = await requestDeliverables(projectRoot);      expect(response.status).toBe(200);     expect(response.body.projectRoot).toBe(projectRoot);     expect(response.body.deliverables).toEqual([       {         id: 'DEL-02-02',         name: 'Portal Pipeline Navigation',         pkg: 'PKG-02_Desktop_UI_Workflow',         status: 'in_progress',         path: deliverablePath       }     ]);     expect(response.body.knowledgeDecomposition).toEqual({       enabled: true,       markerFile: path.join(projectRoot, '_Decomposition', 'Domain_Handbook.md')     });     expect(response.body.knowledgeTypes).toEqual(       expect.arrayContaining([         {           id: 'datasheet',           label: 'Datasheet',           matchingDeliverableKeys: ['PKG-02_Desktop_UI_Workflow::DEL-02-02']         },         {           id: 'specification',           label: 'Specification',           matchingDeliverableKeys: ['PKG-02_Desktop_UI_Workflow::DEL-02-02']         },         {           id: 'memory',           label: 'Memory',           matchingDeliverableKeys: ['PKG-02_Desktop_UI_Workflow::DEL-02-02']         }       ])     );   });    it('returns marker disabled when no decomposition marker is present', async () => {     await createDeliverable(       'PKG-06_Agent_Suite_Governance',       'DEL-06-03_Cross_Deliverable_Workflows',       'SEMANTIC_READY',       ['Guidance.md']     );      const decompositionPath = path.join(projectRoot, '_Decomposition');     await mkdir(decompositionPath, { recursive: true });     await writeFile(       path.join(decompositionPath, 'ChiralityApp_SoftwareDecomposition.md'),       '# Software Decomposition

No domain marker text.',       'utf8'     );      const response = await requestDeliverables(projectRoot);     expect(response.status).toBe(200);     expect(response.body.knowledgeDecomposition).toEqual({       enabled: false,       markerFile: null     });   });    it('returns typed accessibility failures for missing project roots', async () => {     const response = await requestDeliverables(path.join(projectRoot, 'missing-root'));     expect(response.status).toBe(404);     expect(response.body).toMatchObject({       error: {         type: 'WORKING_ROOT_INACCESSIBLE'       }     });   }); });

import { describe, expect, it } from 'vitest'; import { readDependencyRegister } from '../../lib/dependencies/register-reader'; import { serializeDependencyRegister } from '../../lib/dependencies/register-writer'; import {   DEPENDENCY_CORE_COLUMNS,   DependencyContractError,   DependencyRegisterRow } from '../../lib/dependencies/schema';  function makeRow(overrides: Partial<DependencyRegisterRow> = {}): DependencyRegisterRow {   return {     RegisterSchemaVersion: 'v3.1',     DependencyID: 'DEP-05-03-001',     FromPackageID: 'PKG-05',     FromDeliverableID: 'DEL-05-03',     FromDeliverableName: 'Lifecycle State Handling',     DependencyClass: 'EXECUTION',     AnchorType: 'NOT_APPLICABLE',     Direction: 'UPSTREAM',     DependencyType: 'PREREQUISITE',     TargetType: 'DELIVERABLE',     TargetPackageID: 'PKG-05',     TargetDeliverableID: 'DEL-05-02',     TargetRefID: '',     TargetName: 'Execution Root Scaffolding',     TargetLocation: '',     Statement: 'Requires scaffolding baseline before lifecycle transitions',     EvidenceFile: 'Specification.md',     SourceRef:       'execution/PKG-05_Filesystem_Execution_Model/1_Working/DEL-05-03_Lifecycle_State_Handling/Specification.md#REQ-01',     EvidenceQuote: 'Ensure lifecycle is represented by _STATUS.md.',     Explicitness: 'EXPLICIT',     RequiredMaturity: 'IN_PROGRESS',     ProposedMaturity: 'IN_PROGRESS',     SatisfactionStatus: 'PENDING',     Confidence: 'HIGH',     Origin: 'EXTRACTED',     FirstSeen: '2026-02-22',     LastSeen: '2026-02-22',     Status: 'ACTIVE',     Notes: '',     ...overrides   }; }  function buildLegacyCsv(row: DependencyRegisterRow): string {   const headers = DEPENDENCY_CORE_COLUMNS.filter(     (column) => column !== 'RegisterSchemaVersion'   );   const values = headers.map((header) => row[header] ?? '');   return `${headers.join(',')}
${values.join(',')}
`; }  describe('dependency register reader/writer', () => {   it('reads legacy csv and normalizes direction + schema version', () => {     const csv = buildLegacyCsv(       makeRow({         Direction: 'INBOUND',         DependencyType: 'COORDINATION'       })     );      const result = readDependencyRegister(csv);     expect(result.warnings).toContain('MISSING_SCHEMA_VERSION_COLUMN');     expect(result.rows[0].RegisterSchemaVersion).toBe('v3.1');     expect(result.rows[0].Direction).toBe('UPSTREAM');     expect(result.rows[0].DependencyType).toBe('OTHER');   });    it('serializes rows with canonical core header ordering', () => {     const result = serializeDependencyRegister([makeRow()], {       hostDeliverableId: 'DEL-05-03'     });      const [headerLine] = result.csv.split('
');     expect(headerLine).toBe(DEPENDENCY_CORE_COLUMNS.join(','));     expect(result.rows[0].RegisterSchemaVersion).toBe('v3.1');   });    it('rejects invalid ANCHOR classification', () => {     expect(() =>       serializeDependencyRegister([         makeRow({           DependencyClass: 'ANCHOR',           AnchorType: 'NOT_APPLICABLE',           DependencyType: 'OTHER'         })       ])     ).toThrowError(       expect.objectContaining({         code: 'INVALID_CLASSIFICATION'       }) satisfies Partial<DependencyContractError>     );   });    it('rejects active rows without required provenance', () => {     expect(() =>       serializeDependencyRegister([         makeRow({           EvidenceFile: '',           SourceRef: ''         })       ])     ).toThrowError(       expect.objectContaining({         code: 'INVALID_PROVENANCE'       }) satisfies Partial<DependencyContractError>     );   });    it('enforces target resolution rules', () => {     expect(() =>       serializeDependencyRegister([         makeRow({           TargetType: 'DELIVERABLE',           TargetDeliverableID: ''         })       ])     ).toThrowError(       expect.objectContaining({         code: 'INVALID_TARGET'       }) satisfies Partial<DependencyContractError>     );      expect(() =>       serializeDependencyRegister([         makeRow({           TargetType: 'DOCUMENT',           TargetDeliverableID: 'DEL-05-02'         })       ])     ).toThrowError(       expect.objectContaining({         code: 'INVALID_TARGET'       }) satisfies Partial<DependencyContractError>     );   });    it('rejects duplicate dependency ids', () => {     expect(() =>       serializeDependencyRegister([makeRow(), makeRow()])     ).toThrowError(       expect.objectContaining({         code: 'DUPLICATE_DEPENDENCY_ID'       }) satisfies Partial<DependencyContractError>     );   });    it('enforces satisfaction status transition rules against previous rows', () => {     const previous = makeRow({       DependencyID: 'DEP-05-03-009',       SatisfactionStatus: 'PENDING'     });      const invalidNext = makeRow({       DependencyID: 'DEP-05-03-009',       SatisfactionStatus: 'SATISFIED'     });      expect(() =>       serializeDependencyRegister([invalidNext], {         previousRows: [previous]       })     ).toThrowError(       expect.objectContaining({         code: 'INVALID_SATISFACTION_TRANSITION'       }) satisfies Partial<DependencyContractError>     );   });    it('accepts valid satisfaction status progression', () => {     const previous = makeRow({       DependencyID: 'DEP-05-03-010',       SatisfactionStatus: 'IN_PROGRESS'     });      const next = makeRow({       DependencyID: 'DEP-05-03-010',       SatisfactionStatus: 'SATISFIED'     });      const result = serializeDependencyRegister([next], {       previousRows: [previous]     });      expect(result.rows[0].SatisfactionStatus).toBe('SATISFIED');   }); });

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'; import {   HarnessApiClientError,   bootHarnessSession,   createHarnessSession,   scaffoldHarnessExecutionRoot,   streamHarnessTurn } from '../../lib/harness/client';  function jsonResponse(payload: unknown, status = 200): Response {   return new Response(JSON.stringify(payload), {     status,     headers: {       'Content-Type': 'application/json'     }   }); }  function sseResponse(chunks: string[]): Response {   const encoder = new TextEncoder();   let index = 0;    const stream = new ReadableStream<Uint8Array>({     pull(controller) {       if (index >= chunks.length) {         controller.close();         return;       }        controller.enqueue(encoder.encode(chunks[index]));       index += 1;     }   });    return new Response(stream, {     status: 200,     headers: {       'Content-Type': 'text/event-stream; charset=utf-8'     }   }); }  beforeEach(() => {   vi.stubGlobal('fetch', vi.fn()); });  afterEach(() => {   vi.unstubAllGlobals();   vi.restoreAllMocks(); });  describe('harness client helpers', () => {   it('creates sessions through create route', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       jsonResponse({         session: {           sessionId: 'sess_1',           projectRoot: '/tmp/project',           persona: 'WORKING_ITEMS',           mode: 'WORKBENCH',           createdAt: '2026-02-23T00:00:00.000Z',           updatedAt: '2026-02-23T00:00:00.000Z'         }       })     );      const session = await createHarnessSession({       projectRoot: '/tmp/project',       persona: 'WORKING_ITEMS',       mode: 'WORKBENCH'     });      expect(session.sessionId).toBe('sess_1');     const [input, init] = fetchMock.mock.calls[0] as [string, RequestInit];     expect(input).toBe('/api/harness/session/create');     expect(init.method).toBe('POST');   });    it('surfaces typed boot errors for non-2xx responses', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       jsonResponse(         {           error: {             type: 'PERSONA_NOT_FOUND',             message: 'Persona not found'           }         },         404       )     );      await expect(bootHarnessSession({ sessionId: 'sess_1' })).rejects.toEqual(       expect.objectContaining({         name: 'HarnessApiClientError',         status: 404,         code: 'PERSONA_NOT_FOUND'       }) satisfies Partial<HarnessApiClientError>     );   });    it('parses SSE frames for streaming turns', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       sseResponse([         'event: chat:delta
data: {"text":"Hel"}

',         'event: chat:delta
data: {"text":"lo"}

',         'event: chat:complete
data: {"text":"Hello"}

',         'event: process:exit
data: {"exitCode":0}

'       ])     );      const events: Array<{ event: string; data: unknown }> = [];      await streamHarnessTurn(       {         sessionId: 'sess_1',         message: 'hello'       },       (event) => {         events.push(event);       }     );      expect(events.map((entry) => entry.event)).toEqual([       'chat:delta',       'chat:delta',       'chat:complete',       'process:exit'     ]);     expect(fetchMock).toHaveBeenCalledWith(       '/api/harness/turn',       expect.objectContaining({         method: 'POST'       })     );   });    it('supports attachment-only turn payloads with string path arrays', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       sseResponse([         'event: process:exit\ndata: {"exitCode":0}\n\n'       ])     );      await streamHarnessTurn(       {         sessionId: 'sess_1',         message: '',         attachments: ['/tmp/sample.txt'],         opts: {           model: 'claude-test',           maxTurns: 3         }       },       () => {         // no-op       }     );      const [, init] = fetchMock.mock.calls[0] as [string, RequestInit];     expect(init.body).toBe(       JSON.stringify({         sessionId: 'sess_1',         message: '',         attachments: ['/tmp/sample.txt'],         opts: {           model: 'claude-test',           maxTurns: 3         }       })     );   });    it('parses typed process-exit error payloads from SSE responses', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       sseResponse([         'event: session:init
data: {"claudeSessionId":"claude_1","model":"claude-test"}

',         'event: process:exit
data: {"exitCode":1,"error":"Turn failed before completion","errorType":"SDK_FAILURE","status":500,"errorDetails":{"marker":"TURN_SDK_FAIL_TEST"}}

'       ])     );      const events: Array<{ event: string; data: unknown }> = [];      await streamHarnessTurn(       {         sessionId: 'sess_1',         message: 'TURN_SDK_FAIL_TEST'       },       (event) => {         events.push(event);       }     );      expect(events).toHaveLength(2);     expect(events[1].event).toBe('process:exit');     expect(events[1].data).toMatchObject({       exitCode: 1,       errorType: 'SDK_FAILURE',       status: 500,       errorDetails: {         marker: 'TURN_SDK_FAIL_TEST'       }     });   });    it('parses typed turn:error payloads from SSE responses', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       sseResponse([         'event: turn:error
data: {"phase":"mid-stream","errorType":"SDK_FAILURE","message":"Turn failed before completion","status":500,"severity":"error","fatal":true,"details":{"marker":"TURN_SDK_FAIL_TEST"}}

',         'event: process:exit
data: {"exitCode":1,"errorType":"SDK_FAILURE","status":500}

'       ])     );      const events: Array<{ event: string; data: unknown }> = [];      await streamHarnessTurn(       {         sessionId: 'sess_1',         message: 'TURN_SDK_FAIL_TEST'       },       (event) => {         events.push(event);       }     );      expect(events).toHaveLength(2);     expect(events[0].event).toBe('turn:error');     expect(events[0].data).toMatchObject({       phase: 'mid-stream',       errorType: 'SDK_FAILURE',       status: 500,       severity: 'error',       fatal: true,       details: {         marker: 'TURN_SDK_FAIL_TEST'       }     });   });    it('scaffolds execution roots through scaffold route', async () => {     const fetchMock = vi.mocked(fetch);     fetchMock.mockResolvedValueOnce(       jsonResponse({         executionRoot: '/tmp/execution',         decompositionPath: '/tmp/decomposition.md',         copiedDecompositionPath: '/tmp/execution/_Decomposition/decomposition.md',         projectName: 'Example',         coordinationMode: 'DEPENDENCY_TRACKED',         packageCount: 1,         deliverableCount: 1,         created: {           directories: ['/tmp/execution/_Coordination'],           files: ['/tmp/execution/INIT.md']         },         layoutValidation: {           valid: true,           executionRoot: {             path: '/tmp/execution',             valid: true,             missing: []           },           packages: [],           deliverables: []         },         preparationCompatibility: {           ready: true,           deliverablesChecked: 1,           issueCount: 0,           deliverables: []         }       })     );      const result = await scaffoldHarnessExecutionRoot({       executionRoot: '/tmp/execution',       decompositionPath: '/tmp/decomposition.md'     });      expect(result.layoutValidation.valid).toBe(true);     expect(result.preparationCompatibility.ready).toBe(true);     const [input, init] = fetchMock.mock.calls[0] as [string, RequestInit];     expect(input).toBe('/api/harness/scaffold');     expect(init.method).toBe('POST');   }); });

function isRowEmpty(row: string[]): boolean {   return row.every((value) => value.trim() === ''); }  export function parseCsv(content: string): string[][] {   const rows: string[][] = [];   let currentRow: string[] = [];   let field = '';   let inQuotes = false;    for (let index = 0; index < content.length; index += 1) {     const char = content[index];      if (inQuotes) {       if (char === '"') {         const nextChar = content[index + 1];         if (nextChar === '"') {           field += '"';           index += 1;           continue;         }         inQuotes = false;         continue;       }        field += char;       continue;     }      if (char === '"') {       inQuotes = true;       continue;     }      if (char === ',') {       currentRow.push(field);       field = '';       continue;     }      if (char === '
') {       currentRow.push(field);       if (!isRowEmpty(currentRow)) {         rows.push(currentRow);       }       currentRow = [];       field = '';       continue;     }      if (char === '') {       continue;     }      field += char;   }    currentRow.push(field);   if (!isRowEmpty(currentRow)) {     rows.push(currentRow);   }    return rows; }  function escapeCsvCell(value: string): string {   const needsQuotes = /[",
]/.test(value);   if (!needsQuotes) {     return value;   }    return `"${value.replace(/"/g, '""')}"`; }  export function serializeCsv(headers: string[], rows: Record<string, string>[]): string {   const lines: string[] = [];   lines.push(headers.join(','));    for (const row of rows) {     const cells = headers.map((header) => escapeCsvCell(row[header] ?? ''));     lines.push(cells.join(','));   }    return `${lines.join('
')}
`; }

import { NextResponse } from 'next/server'; import { asHarnessError, HarnessError } from './errors'; import { HarnessErrorResponse } from './types';  export async function readJsonBody<T>(request: Request): Promise<T> {   try {     return (await request.json()) as T;   } catch {     throw new HarnessError('INVALID_REQUEST', 400, 'Request body must be valid JSON');   } }  export function requireNonEmptyString(value: unknown, field: string): string {   if (typeof value !== 'string' || value.trim().length === 0) {     throw new HarnessError('INVALID_REQUEST', 400, `Missing or invalid '${field}'`);   }    return value.trim(); }  export function requireStringArray(value: unknown, field: string): string[] {   if (!Array.isArray(value) || value.some((item) => typeof item !== 'string')) {     throw new HarnessError('INVALID_REQUEST', 400, `Field '${field}' must be an array of strings`);   }    return value; }  export function errorResponse(error: unknown): NextResponse<HarnessErrorResponse> {   const harnessError = asHarnessError(error);   return NextResponse.json(     {       error: {         type: harnessError.type,         message: harnessError.message,         details: harnessError.details       }     },     { status: harnessError.status }   ); }  export function formatSseEvent(event: string, data: unknown): string {   return `event: ${event}
data: ${JSON.stringify(data)}

`; }

import type { Options, PermissionMode, SettingSource } from '@anthropic-ai/claude-agent-sdk'; import { createChiralityToolHooks } from './chirality-hooks'; import { ContentBlock, ResolvedOpts, SessionRecord } from './types'; import {   createHarnessCanUseTool,   normalizeHarnessPermissionMode } from './permission-overlay'; import { getHarnessToolDescriptor, resolveHarnessToolPool } from './tool-descriptor'; import {   createChiralityReadMcpServers,   filterChiralityMcpAllowedToolNames } from './mcp/read-tools';  export type SdkProbeOptions = Options & {   settingSources: SettingSource[]; };  function parseSettingSources(raw: string | undefined): SettingSource[] {   if (!raw || raw.trim().length === 0) {     return [];   }    const requested = raw     .split(',')     .map((item) => item.trim())     .filter(Boolean);    if (requested.length === 1 && requested[0] === 'project') {     return ['project'];   }    return []; }  function mapPermissionMode(mode: string): PermissionMode {   const normalizedMode = normalizeHarnessPermissionMode(mode);   if (normalizedMode === 'readOnly' || normalizedMode === 'dontAsk') {     return 'dontAsk';   }   if (normalizedMode === 'workspaceWrite') {     return 'acceptEdits';   }   if (     normalizedMode === 'bypass' &&     process.env.CHIRALITY_ALLOW_SDK_BYPASS === '1'   ) {     return 'bypassPermissions';   }   return 'default'; }  function contentBlocksToPrompt(message: string, contentBlocks?: ContentBlock[]): string {   if (!contentBlocks || contentBlocks.length === 0) {     return message;   }    const attachmentSummary = contentBlocks     .map((block) => {       if (block.type === 'text') {         return block.text;       }       return `[Attachment: ${block.path} (${block.mimeType})]`;     })     .join('

');    return [message, attachmentSummary].filter((part) => part.trim().length > 0).join('

'); }  export function buildSdkPrompt(message: string, contentBlocks?: ContentBlock[]): string {   return contentBlocksToPrompt(message, contentBlocks); }  export function buildSdkOptions(input: {   session: SessionRecord;   opts: ResolvedOpts;   abortController: AbortController;   systemPrompt: string; }): SdkProbeOptions {   const toolPool = resolveHarnessToolPool({     sessionId: input.session.sessionId,     requestedTools: input.opts.tools,     mode: input.opts.mode   });   const allowedChiralityMcpToolNames = filterChiralityMcpAllowedToolNames(     toolPool.allowedToolNames   );    return {     abortController: input.abortController,     cwd: input.session.projectRoot,     model: input.opts.model,     maxTurns: input.opts.maxTurns,     permissionMode: mapPermissionMode(input.opts.mode),     tools: [...toolPool.allowedToolNames],     allowedTools: [...toolPool.allowedToolNames],     disallowedTools: [...toolPool.disallowedToolNames],     canUseTool: createHarnessCanUseTool({       sessionId: input.session.sessionId,       mode: input.opts.mode,       projectRoot: input.session.projectRoot,       resolveDescriptor: getHarnessToolDescriptor     }),     hooks: createChiralityToolHooks({       sessionId: input.session.sessionId,       projectRoot: input.session.projectRoot,       resolveDescriptor: getHarnessToolDescriptor     }),     mcpServers: createChiralityReadMcpServers({       context: {         projectRoot: input.session.projectRoot,         sessionId: input.session.sessionId       },       allowedToolNames: allowedChiralityMcpToolNames     }),     resume: input.session.sdkSessionId,     settingSources: parseSettingSources(process.env.CHIRALITY_SDK_SETTING_SOURCES),     systemPrompt: {       type: 'preset',       preset: 'claude_code',       append: input.systemPrompt     }   }; }
